mapper.select:
SELECT M.SCHEDULE_SEQ, M.IF_CODE, M.IF_PARENT_CODE, M.REQUIRED_YN,
       M.PROCEDURE_ID, M.AUTO_BATCH_YN
  FROM INTERFACE_SCHEDULE_MAPPING M
 WHERE M.SCHEDULE_CODE = #{schedule_code}
   AND M.COMPANY_CODE = #{company_code}
 ORDER BY M.SCHEDULE_SEQ

mapper.insert:
INSERT INTO INTERFACE_SCHEDULE_MAPPING (
    SCHEDULE_CODE, COMPANY_CODE, SCHEDULE_SEQ, IF_CODE, IF_PARENT_CODE,
    REQUIRED_YN, PROCEDURE_ID, AUTO_BATCH_YN, CREATE_DATE, CREATE_BY, UPDATE_DATE, UPDATE_BY
) VALUES (
    #{schedule_code}, #{company_code}, CAST(#{schedule_seq} AS SMALLINT), #{if_code},
    NULLIF(#{if_parent_code}, ''), #{required_yn}, NULLIF(#{procedure_id}, ''), #{auto_batch_yn},
    NOW(), #{update_by}, NOW(), #{update_by}
)

mapper.update:
UPDATE INTERFACE_SCHEDULE
   SET STATUS = '0', EXTCUTION_MESSAGE = NULL, UPDATE_DATE = NOW(), UPDATE_BY = #{update_by}
 WHERE SCHEDULE_CODE = #{schedule_code} AND COMPANY_CODE = #{company_code}
